/**
 * Represents a payment concept within the school's financial system, containing details about the concept's name, description, amount, and other relevant information.
 * This entity is used to define various payment concepts that can be associated with student wallet payments, allowing for better organization and management of different types of payments within the school.
 */
export interface PaymentConcept {
    /**
     * Required - Unique identifier for the payment concept, generated by backend
     */
    id: string;
    /**
     * Required - Name of the payment concept
     * Example: "Colegiatura", "Materiales escolares"
     */
    name: string;
    /**
     * Required - Description of the payment concept
     * Example: "Pago por concepto de colegiatura"
     */
    description: string;
    /**
     * Required - Indicates if the payment concept allows forgiveness
     */
    allowForgiveness: boolean;
    /**
     * Required - Amount associated with the payment concept
     */
    amount: number;
    /**
     * Required - Indicates if the payment concept is active
     */
    status: boolean;
}
